const args = process.argv.slice(2);
const part = (() => { const i = args.indexOf("--part"); if (i < 0) return null; const [k, n] = args[i + 1].split("/").map(Number); return { k, n }; })();
const only = (() => { const i = args.indexOf("--only"); return i >= 0 ? new Set(args[i + 1].split(",")) : null; })();
const inPart = (i) => !part || i % part.n === part.k - 1;
// --list [--part k/n]: print the ids this part runs, one a line, and stop (no site, no browser). The workflow reads it to
// install Firefox and WebKit only in the part that runs UX/U1.md:261. The ids are read from this file's C("...") lines,
// which are the checks in the order they run.
if (args.includes("--list")) {
  const ids = [...readFileSync(new URL(import.meta.url), "utf8").matchAll(/^C\("([^"]+)"/gm)].map((m) => m[1]);
  console.log(ids.filter((_, i) => inPart(i)).join("\n")); process.exit(0);
}
// tests/web/law_not_met.json: { "<check id>": { "reason": "<at most 20 words>", "needs": "person" | "outside account" |
// "spending" | "law conflict" | "host limit" } }. "law conflict" also names, in "won_by", the rule that wins ("UX/U3.md:21":
// a law file and line, another check's rule; the winner is the law with authority, else the one with fewer words on the
// screen); "host limit" says in "why" what the host does not let the site do.
// A check listed there that fails ONLY for what the person, the account, the winning rule or the host stands in the way
// of (the check returns `wait`, that part, measured, and `rest`, whether everything else it measures passes) prints
// NOT MET and does not fail the job. A listed check that fails for anything else fails as usual; one that passes, or is
// not applicable, fails with "remove it from law_not_met.json"; an unknown id, a "needs" outside the five values, or a
// "won_by" or "why" missing where its "needs" asks for one fails.
const NEEDS = ["person", "outside account", "spending", "law conflict", "host limit"];
const RULE_AT = /^(UX|DISTRIBUTION|SYNC|MISSION)\/[\w.-]+\.md:\d+$/;
const NOT_MET = JSON.parse(readFileSync(new URL("./law_not_met.json", import.meta.url), "utf8"));
const T_START = Date.now();
const env = await setup(args[0]);
const SLOW4G = [1638.4, 750, 150];                   // Lighthouse's "Slow 4G": 1.6 Mbps down, 750 kbps up, 150 ms
// U3's test viewports: the three phone projects of the repository's playwright.config.mjs (U3.md line 177: every check of
// U3 runs in all three); UX/U3.md:177 fails when one of them is missing there
const TEST_VP = await import("../../playwright.config.mjs").then((m) => m.default.projects.map((p) => [p.use.viewport.width, p.use.viewport.height])).catch(() => [[360, 780], [390, 844], [414, 896]]);
const GO = { door: "#try", tool: "#go", result: "#go" };
const RESULT = { door: "#result, #about", tool: "#out .big, #out p", result: "#out .big, #out p" };
const fmt = (n) => (n === Infinity ? "none in 3 s" : n == null ? "n/a" : typeof n === "number" ? String(Math.round(n * 100) / 100) : String(n));
const cut = (s, n = 160) => { s = String(s); return s.length > n ? s.slice(0, n) + "…" : s; };

// a screen that moves on by itself after load (a language or address change) is read once it has settled
async function safeEval(page, f, arg) {
  for (let i = 0; ; i++) {
    try { return await page.evaluate(f, arg); } catch (e) {
      if (i >= 3 || !/Execution context was destroyed|navigat/i.test(String(e.message))) throw e;
      await page.waitForLoadState("load").catch(() => {}); await page.waitForTimeout(300);
    }
  }
}
// ---- caches -------------------------------------------------------------------------------------------------------------
const memo = new Map();
const once = (key, f) => { if (!memo.has(key)) memo.set(key, f()); return memo.get(key); };
const S = (screen, o = {}) => once("S" + screen + JSON.stringify(o), async () => {
  const page = await env.open(screen, o);
  if (o.css) await page.addStyleTag({ content: o.css });
  if (o.css) await page.waitForTimeout(100);
  const s = await safeEval(page, SURVEY); await page.context().close(); return s;
});
const AX = (screen, o = {}, opts = {}) => once("A" + screen + JSON.stringify(o) + JSON.stringify(opts), async () => {
  const page = await env.open(screen, o); const r = await env.axe(page, opts); await page.context().close(); return r;
});
const axeText = (r) => r.error ? r.error : r.violations.length ? r.violations.map((v) => `${v.id} x${v.n} (${v.at})`).join("; ") : "0 violations";
const P = (name, o) => once("P" + name, () => excl(() => pressAll(env, SCREENS, o)));
const pressSummary = (list, limit, key = "ms") => {
  const timed = list.filter((x) => x[key] !== undefined && !x.skipped);
  const worst = [...timed].sort((a, b) => (b[key] ?? 0) - (a[key] ?? 0))[0];
  const over = timed.filter((x) => !(x[key] <= limit));
  return { ok: over.length === 0 && timed.length > 0, v: `${timed.length} controls timed (${list.length - timed.length} not: links to other sites or disabled); slowest ${worst ? `${fmt(worst[key])} ms, ${worst.screen} ${worst.name}` : "none"}; over ${limit} ms: ${over.length}${over.length ? " (" + over.slice(0, 4).map((x) => `${x.screen} ${x.name} ${fmt(x[key])}${x.how && x.how !== "same page" ? " " + x.how : ""}`).join("; ") + ")" : ""}` };
};
const eachP = (screens, f) => excl(async () => { const rs = await Promise.all(screens.map(async (s) => ({ s, ...(await f(s)) }))); return { ok: rs.every((r) => r.ok), v: rs.map((r) => `${r.s}: ${r.v}`).join("; ") }; });
// each screen side by side (pages that only read; a time measure inside takes the page budget alone, see excl)
const each = async (screens, f) => { const rs = await Promise.all(screens.map(async (s) => ({ s, ...(await f(s)) }))); return { ok: rs.every((r) => r.ok), v: rs.map((r) => `${r.s}: ${r.v}`).join("; ") }; };
const eachT = (screens, f) => excl(async () => { const rs = []; for (const s of screens) rs.push({ s, ...(await f(s)) }); return { ok: rs.every((r) => r.ok), v: rs.map((r) => `${r.s}: ${r.v}`).join("; ") }; });
const all = (...rs) => ({ ok: rs.every((r) => r.ok), v: rs.map((r) => r.v).join(" | ") });
const RESULTS = {};
const ref = async (id) => { if (!RESULTS[id]) await runOne(id); return RESULTS[id]; };

const VITALS = () => {
  window.__v = { lcp: 0, lcpEl: null, cls: 0, long: [], types: [] };
  try { new PerformanceObserver((l) => { for (const e of l.getEntries()) { window.__v.lcp = e.startTime; window.__v.lcpNode = e.element; } }).observe({ type: "largest-contentful-paint", buffered: true }); } catch { /* none */ }
  try { new PerformanceObserver((l) => { for (const e of l.getEntries()) if (!e.hadRecentInput) window.__v.cls += e.value; }).observe({ type: "layout-shift", buffered: true }); } catch { /* none */ }
  try { new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__v.long.push([e.startTime, e.duration]); }).observe({ type: "longtask", buffered: true }); } catch { /* none */ }
};
const vitals = (screen, o) => once("V" + screen + JSON.stringify(o), () => excl(async () => {
  const page = await env.open(screen, { ...o, init: VITALS, settle: o.wait || 3000 });
  const v = await page.evaluate((screen) => {
    const fcpE = performance.getEntriesByName("first-contentful-paint")[0], fcp = fcpE ? fcpE.startTime : null;
    const n = window.__v.lcpNode, main = document.querySelector("main") || document.body;
    const list = document.getElementById("list"), lab = list && list.labels && list.labels[0];
    const isMain = !n ? false : screen === "door" || screen === "tool" ? (n === list || n === lab || (lab && lab.contains(n)))
      : screen === "result" ? (n === list || n === lab || !!(n.closest && n.closest("#out"))) : !!(main.contains(n) && !n.closest("header, footer, nav"));
    const tbt = window.__v.long.filter(([s]) => fcp === null || s >= fcp).reduce((t, [, d]) => t + Math.max(0, d - 50), 0);
    return { fcp, lcp: window.__v.lcp, cls: window.__v.cls, tbt, el: n ? (n.id ? "#" + n.id : n.tagName.toLowerCase()) + (n.textContent ? ` "${n.textContent.trim().slice(0, 25)}"` : "") : "none", isMain };
  }, screen);
  const res = await page.evaluate(() => performance.getEntriesByType("resource").map((r) => ({ name: r.name, type: r.initiatorType, size: r.encodedBodySize, transfer: r.transferSize })));
  await page.context().close();
  return { ...v, res };
}));
// the bytes each screen loads, with what gzip (as GitHub Pages and the app's host send them) makes of each
const bytes = (screen, o = {}) => once("B" + screen + JSON.stringify(o), async () => {
  const ctx = await env.context(o); const page = await ctx.newPage(); const got = [];
  page.on("response", async (r) => { try { const b = await r.body(); got.push({ url: r.url(), type: r.request().resourceType(), raw: b.length, gz: gzipSync(b).length, headers: r.headers() }); } catch { /* aborted */ } });
  if (o.cpu || o.net) { const cdp = await ctx.newCDPSession(page); if (o.cpu) await cdp.send("Emulation.setCPUThrottlingRate", { rate: o.cpu }); if (o.net) { await cdp.send("Network.enable"); await cdp.send("Network.emulateNetworkConditions", { offline: false, downloadThroughput: o.net[0] * 1024 / 8, uploadThroughput: o.net[1] * 1024 / 8, latency: o.net[2] }); } }
  const resp = await page.goto(env.URLS[screen], { waitUntil: "load", timeout: 60000 }); await page.waitForTimeout(1000);
  const reqs = ctx.law.requests.map((r) => r); await ctx.close();
  const kb = (t) => got.filter((g) => !t || t(g)).reduce((s, g) => s + g.gz, 0) / 1024;
  return { got, reqs, total: kb(), js: kb((g) => g.type === "script"), fonts: kb((g) => g.type === "font"), mainHeaders: resp ? resp.headers() : {} };
});

// press the screen's run control with the run answered after `delay` ms; `watch(page, t0)` samples while it waits
async function delayedRun(screen, o, watch) {
  const page = await env.open(screen, { w: 390, h: 844, ...o });
  await page.evaluate(ARM);
  await page.click(GO[screen], { timeout: 5000 });
  const out = await watch(page);
  await page.context().close();
  return out;
}
const firstChangeMs = (page) => page.waitForFunction(() => window.__law.done !== undefined, null, { timeout: 3000, polling: 16 }).then(() => page.evaluate(() => window.__law.done)).catch(() => Infinity);
const waitingState = (page) => page.evaluate(() => {
  const vis = (el) => { const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0 && getComputedStyle(el).visibility !== "hidden"; };
  const bar = [...document.querySelectorAll('[role="progressbar"]')].find(vis);
  const busy = [...document.querySelectorAll('[aria-busy="true"]')].find(vis);
  const status = [...document.querySelectorAll('[role="status"], [role="progressbar"], [aria-live]')].filter(vis).map((e) => e.textContent.trim()).filter(Boolean);
  const state = document.querySelector("[data-state]");
  return { bar: !!bar, now: bar ? bar.getAttribute("aria-valuenow") : null, barText: bar ? bar.textContent.trim() : "", busy: !!busy, status, state: state ? state.getAttribute("data-state") : null,
    text: (document.getElementById("out") || document.getElementById("state") || document.body).innerText.slice(0, 200), anims: document.getAnimations().map((a) => ({ d: a.effect && a.effect.getTiming ? a.effect.getTiming().duration : 0, it: a.effect && a.effect.getTiming ? a.effect.getTiming().iterations : 1, el: a.effect && a.effect.target ? (a.effect.target.className || a.effect.target.tagName) : "" })) };
});
const resultShown = (page, screen, timeout = 20000) => page.waitForFunction((sel) => [...document.querySelectorAll(sel)].some((e) => /^(Failed at row |Passed: all )/.test(e.textContent.trim()) && e.getBoundingClientRect().height > 0), RESULT[screen], { timeout }).then(() => true).catch(() => false);

// locale files: web/i18n/<code>.json, as the language builder of Round 13 writes them
const I18N = join(ROOT, "web", "i18n");
const localeFiles = () => existsSync(I18N) ? readdirSync(I18N).filter((f) => f.endsWith(".json")).map((f) => { let j = null; try { j = JSON.parse(readFileSync(join(I18N, f), "utf8")); } catch { j = null; } return { f, code: f.replace(/\.json$/, ""), j }; }) : [];
// the strings of a locale file, its "_meta" block left out (web/i18n/<code>.json: {"_meta": {...}, "strings": {...}})
// a message is a string, an object with its text ({"text", "description", "max_length"}), or a plural message whose forms
