const flat = (o, p = "") => Object.entries(o || {}).filter(([k]) => !k.startsWith("_")).flatMap(([k, v]) => v && typeof v === "object" && !Array.isArray(v) && !("text" in v || "message" in v || "other" in v) ? flat(v, p + k + ".") : [[p + k, v]]);
