// ---- Flesch-Kincaid grade as textstat 0.7.13 computes it, in Python (U2 R8): the screens' English text to `textstat`
const PY = process.env.PYTHON || "python3";
function textstat(texts) {
  const code = "import json,sys\ntry:\n import textstat\nexcept Exception as e:\n print(json.dumps({'error':'textstat is not installed: '+str(e)}));sys.exit(0)\nd=json.load(sys.stdin)\nprint(json.dumps({k:{'grade':textstat.flesch_kincaid_grade(t),'poly':textstat.polysyllabcount(t),'words':textstat.lexicon_count(t)} for k,t in d.items()}))";
  const r = spawnSync(PY, ["-c", code], { input: JSON.stringify(texts), encoding: "utf8" });
  try { return JSON.parse(r.stdout); } catch { return { error: "textstat run failed: " + (r.stderr || r.stdout).slice(0, 200) }; }
}
const asProse = (x) => (x.blocks || [x.text]).map((t) => (/[.!?。！？]$/.test(t) ? t : t + ".")).join("\n");
const sentences = (text, locale = "en") => { const seg = new Intl.Segmenter(locale, { granularity: "sentence" }); const ws = new Intl.Segmenter(locale, { granularity: "word" });
  return [...seg.segment(text)].map((s) => s.segment.trim()).filter(Boolean).map((s) => [...ws.segment(s)].filter((w) => w.isWordLike).length); };

